  // Export session handlers
  const handleExportSession = (format: 'txt' | 'md' | 'code' | 'clipboard') => {
    try {
      // Get terminal content from the terminal session data that's being passed from Terminal component
      const terminalContent = terminalSessionData.terminalHistory || 'No terminal content available';
      
      let exportContent = '';
      let filename = '';
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      
      // Get additional context for comprehensive exports
      const commandHistory = terminalSessionData.terminalCommands || [];
      const editorContent = activeFilePath && openFiles.find(f => f.path === activeFilePath)
        ? openFiles.find(f => f.path === activeFilePath)!.content 
        : fileContent;
      
      switch (format) {
        case 'txt':
          exportContent = terminalContent;
          filename = `terminal-session-${timestamp}.txt`;
          break;
          
        case 'md':
          exportContent = `# CoderOne IDE Session Export\n\n` +
            `**Date:** ${new Date().toLocaleString()}\n` +
            `**Session ID:** ${sessionId}\n\n`;
          
          if (commandHistory.length > 0) {
            exportContent += `## Command History\n\n`;
            commandHistory.slice(-10).forEach((cmd, index) => {
              exportContent += `${index + 1}. \`${cmd}\`\n`;
            });
            exportContent += `\n`;
          }
          
          if (editorContent) {
            exportContent += `## Current File Content\n\n` +
              `**File:** ${activeFilePath || 'Untitled'}\n\n` +
              '```\n' + editorContent + '\n```\n\n';
          }
          
          exportContent += `## Terminal Output\n\n` +
            '```terminal\n' + terminalContent + '\n```';
            
          filename = `coderone-session-${timestamp}.md`;
          break;
          
        case 'code':
          // Extract code from both editor and terminal
          let codeContent = '';
          
          if (editorContent) {
            codeContent += `// File: ${activeFilePath || 'Untitled'}\n`;
            codeContent += editorContent + '\n\n';
          }
          
          // Extract code blocks from terminal content
          const codeMatches = terminalContent.match(/```[\s\S]*?```/g) || [];
          if (codeMatches.length > 0) {
            codeContent += '// Code from terminal output:\n';
            codeContent += codeMatches.join('\n\n');
          }
          
          exportContent = codeContent || 'No code content found';
          filename = `code-export-${timestamp}.txt`;
          break;
          
        case 'clipboard':
          // Create a comprehensive clipboard export
          let clipboardContent = `CoderOne IDE Session - ${new Date().toLocaleString()}\n`;
          clipboardContent += '='.repeat(50) + '\n\n';
          
          if (commandHistory.length > 0) {
            clipboardContent += 'Recent Commands:\n';
            commandHistory.slice(-5).forEach(cmd => {
              clipboardContent += `$ ${cmd}\n`;
            });
            clipboardContent += '\n';
          }
          
          clipboardContent += 'Terminal Output:\n';
          clipboardContent += '-'.repeat(30) + '\n';
          clipboardContent += terminalContent;
          
          navigator.clipboard.writeText(clipboardContent);
          alert('Comprehensive session data copied to clipboard!');
          setShowExportDropdown(false);
          return;
      }
      
      // Download file
      const blob = new Blob([exportContent], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      
      setShowExportDropdown(false);
    } catch (error) {
      console.error('Export error:', error);
      alert('Failed to export session: ' + error);
    }
  };


